"""Shared dependency-free browser assets for live and annotation viewers."""

BOARD_RENDERER_JS = r"""
const names=['Wait','Sunflower','Peashooter','Wall-nut','Cherry Bomb','Potato Mine','Snow Pea','Chomper','Repeater','Dig'];
const reasons=['','occupied_tile','card_recharging','insufficient_sun','empty_tile','task_restriction','game_finished','outside_space'];
const n=(v,d=0)=>Number.isFinite(Number(v))?Number(v):d;
const list=v=>Array.isArray(v)?v:[];
const objectList=v=>list(v).filter(item=>item&&typeof item==='object');
const esc=x=>String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const json=v=>{try{return JSON.stringify(v??{},null,2)}catch(_){return '{}'}};
function normalizeObservation(value){let o=value&&typeof value==='object'?value:{},counts=o.counts&&typeof o.counts==='object'?o.counts:{};return {...o,rows:Math.max(1,n(o.rows,5)),cols:Math.max(1,n(o.cols,9)),units_per_tile:Math.max(1,n(o.units_per_tile,80)),cards:objectList(o.cards),plants:objectList(o.plants),zombies:objectList(o.zombies),projectiles:objectList(o.projectiles),mowers:objectList(o.mowers),counts:{initial_total:n(counts.initial_total),spawned:n(counts.spawned),defeated:n(counts.defeated),alive:n(counts.alive),not_yet_spawned:n(counts.not_yet_spawned),remaining:n(counts.remaining)}}}
function actionName(v){let i=n(v,-1);return names[i]||('Action '+i)}
function reasonName(v){let i=n(v,-1);return reasons[i]||String(v??'unknown')}
function boardGeometry(o){return {rows:Math.max(1,n(o.rows,5)),cols:Math.max(1,n(o.cols,9)),tx:98,ty:110,bx:64,by:226}}
function drawPlant(ctx,p,x,y,s){let kind=String(p.plant_type||'plant'),colors={sunflower:'#f8cf5e',peashooter:'#7fba56',wall_nut:'#c58c4d',cherry_bomb:'#d85c58',potato_mine:'#c99c59',snow_pea:'#82c9cf',chomper:'#b495e5',repeater:'#70b55b'},c=colors[kind]||'#9bc477';ctx.fillStyle='#41643d';ctx.fillRect(x-4*s,y+20*s,8*s,22*s);ctx.fillStyle=c;ctx.beginPath();ctx.arc(x,y,24*s,0,Math.PI*2);ctx.fill();if(kind==='sunflower'){ctx.fillStyle='#f8cf5e';for(let i=0;i<8;i++){let a=i*Math.PI/4;ctx.beginPath();ctx.arc(x+Math.cos(a)*28*s,y+Math.sin(a)*28*s,8*s,0,Math.PI*2);ctx.fill()}}ctx.fillStyle='#203826';ctx.beginPath();ctx.arc(x-7*s,y-3*s,3*s,0,Math.PI*2);ctx.arc(x+7*s,y-3*s,3*s,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e9eddc';ctx.font='11px system-ui';ctx.textAlign='center';ctx.fillText(kind.replaceAll('_',' '),x,y+52*s);ctx.textAlign='start'}
function drawZombie(ctx,z,x,y,s){let slow=n(z.slow_ticks)>0;ctx.fillStyle=slow?'#8ecbe0':'#9db6a7';ctx.beginPath();ctx.arc(x,y-29*s,20*s,0,Math.PI*2);ctx.fill();ctx.fillStyle='#735f75';ctx.fillRect(x-16*s,y-12*s,32*s,38*s);ctx.strokeStyle='#445d49';ctx.lineWidth=7*s;ctx.beginPath();ctx.moveTo(x-8*s,y+24*s);ctx.lineTo(x-13*s,y+43*s);ctx.moveTo(x+8*s,y+24*s);ctx.lineTo(x+13*s,y+43*s);ctx.stroke();if(!z.headless){ctx.fillStyle='#203826';ctx.beginPath();ctx.arc(x-7*s,y-32*s,3*s,0,Math.PI*2);ctx.arc(x+7*s,y-32*s,3*s,0,Math.PI*2);ctx.fill()}if(n(z.armor)>0){ctx.strokeStyle='#dca16a';ctx.lineWidth=5*s;ctx.strokeRect(x-22*s,y-52*s,44*s,12*s)}if(slow){ctx.strokeStyle='#a9e7f2';ctx.lineWidth=2*s;ctx.strokeRect(x-25*s,y-57*s,50*s,65*s)}let total=Math.max(1,n(z.health)+n(z.armor));ctx.fillStyle='#493b3a';ctx.fillRect(x-24,y+37*s,48,4);ctx.fillStyle='#c55b4a';ctx.fillRect(x-24,y+37*s,48*Math.max(0,Math.min(1,n(z.health)/total)),4);ctx.fillStyle='#e9eddc';ctx.font='11px system-ui';ctx.textAlign='center';ctx.fillText(String(z.zombie_type||'zombie').replaceAll('_',' '),x,y+53*s);ctx.textAlign='start'}
function drawBoard(canvas,obs,frame,options={}){let o=normalizeObservation(obs),cssW=Math.max(320,canvas.clientWidth||960),cssH=Math.round(cssW*820/1280),dpr=window.devicePixelRatio||1;canvas.width=Math.round(cssW*dpr);canvas.height=Math.round(cssH*dpr);let ctx=canvas.getContext('2d');if(!ctx)return;ctx.setTransform(dpr*cssW/1280,0,0,dpr*cssW/1280,0,0);ctx.clearRect(0,0,1280,820);ctx.fillStyle='#142724';ctx.fillRect(0,0,1280,820);ctx.fillStyle='#e9eddc';ctx.font='bold 30px system-ui';ctx.fillText('LAWN LAB',34,48);ctx.font='13px system-ui';ctx.fillStyle='#9db49e';ctx.fillText('DAYTIME DEFENSE',236,45);ctx.fillText(`${String(o.level||'board').toUpperCase().slice(0,22)} / ${n(o.elapsed_seconds).toFixed(1)}s`,694,43);let g=boardGeometry(o),rows=g.rows,cols=g.cols,tx=g.tx,ty=g.ty,bx=g.bx,by=g.by;ctx.fillStyle='#5e814c';ctx.fillRect(bx-7,by-7,cols*tx+14,rows*ty+14);for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){ctx.fillStyle=(r+c)%2?'#a7c383':'#b4cc91';ctx.fillRect(bx+c*tx,by+r*ty,tx,ty);ctx.fillStyle='#5d824d';ctx.font='13px system-ui';if(c===0)ctx.fillText(String.fromCharCode(65+r),bx+6,by+r*ty+20)}for(let c=0;c<cols;c++){ctx.fillStyle='#9db49e';ctx.font='13px system-ui';ctx.fillText(c+1,bx+c*tx+tx/2-4,by-23)}let units=Math.max(1,n(o.units_per_tile,80));for(let m of list(o.mowers)){if(m.state==='spent')continue;let x=bx+n(m.x)/units*tx-22,y=by+n(m.row)*ty+ty*.65;ctx.fillStyle='#d36351';ctx.fillRect(x-20,y-13,40,22);ctx.fillStyle='#203826';ctx.beginPath();ctx.arc(x-11,y+11,7,0,Math.PI*2);ctx.arc(x+11,y+11,7,0,Math.PI*2);ctx.fill()}for(let p of list(o.plants)){let x=bx+(n(p.col)+.5)*tx,y=by+(n(p.row)+.53)*ty;drawPlant(ctx,p,x,y,.72);if(n(p.max_health)>0&&n(p.health)<n(p.max_health)){ctx.fillStyle='#596b41';ctx.fillRect(x-24,y+34,48,4);ctx.fillStyle='#368442';ctx.fillRect(x-24,y+34,48*Math.max(0,Math.min(1,n(p.health)/n(p.max_health))),4)}}for(let z of list(o.zombies)){let x=bx+(n(z.x)/units+21/80)*tx,y=by+(n(z.row)+.58)*ty;drawZombie(ctx,z,x,y,.68)}for(let p of list(o.projectiles)){let x=bx+n(p.x)/units*tx,y=by+(n(p.row)+.5)*ty-8;ctx.fillStyle=p.icy?'#afe8f1':'#cce276';ctx.beginPath();ctx.arc(x,y,7,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#3b3f27';ctx.fillRect(978,20,266,70);ctx.fillStyle='#f8cf5e';ctx.beginPath();ctx.arc(1007,54,13,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f8cf5e';ctx.font='bold 30px system-ui';ctx.fillText(n(o.sun),1034,65);ctx.fillStyle='#9db49e';ctx.font='13px system-ui';ctx.fillText('AUTO SUN',1137,58);ctx.fillStyle='#1e362f';ctx.fillRect(978,105,266,100);ctx.fillStyle='#e9eddc';ctx.font='bold 20px system-ui';ctx.fillText(String(o.status||frame?.outcome||'running').toUpperCase(),998,132);ctx.font='13px system-ui';ctx.fillStyle='#9db49e';ctx.fillText(`wave ${n(o.wave)}/${n(o.total_waves)} · defeated ${n(o.counts&&o.counts.defeated)}`,998,163);ctx.fillText(`alive ${n(o.counts&&o.counts.alive)} · remaining ${n(o.counts&&o.counts.remaining)}`,998,185);ctx.fillText(`spawned ${n(o.counts&&o.counts.spawned)} · upcoming ${n(o.counts&&o.counts.not_yet_spawned)}`,998,201);let cards=list(o.cards);for(let i=0;i<Math.min(cards.length,8);i++){let c=cards[i],x=34+i*114;ctx.fillStyle='#1f342e';ctx.fillRect(x,84,105,116);ctx.fillStyle='#d5e4d7';ctx.font='12px system-ui';ctx.fillText(String(i+1),x+9,101);ctx.fillText(String(c.plant_type||'plant').replaceAll('_',' '),x+6,181);ctx.fillStyle='#f8cf5e';ctx.fillText(n(c.cost),x+6,195);if(n(c.cooldown_ticks)>0){ctx.fillStyle='#6a936e';ctx.fillRect(x+8,152,89,4);ctx.fillStyle='#9bd477';ctx.fillRect(x+8,152,89*Math.max(0,1-n(c.cooldown_ticks)/Math.max(1,n(c.recharge_ticks))),4)}}if(frame&&frame.outcome&&frame.outcome!=='running'){ctx.fillStyle='rgba(20,39,36,.82)';ctx.fillRect(420,370,440,115);ctx.fillStyle='#f4efd8';ctx.font='bold 30px system-ui';ctx.fillText(String(frame.outcome).toUpperCase(),565,420);ctx.font='15px system-ui';ctx.fillStyle='#9db49e';ctx.fillText('latest public board snapshot',530,454)}if(options.annotation){if(options.action)drawActionCardOverlay(canvas,o,options.action);else drawTileOverlay(canvas,o,options.selected||[],options.legal||[],options.mode||'add')}}
function tileIndexAt(canvas,obs,event){let o=normalizeObservation(obs),g=boardGeometry(o),rect=canvas.getBoundingClientRect(),x=(event.clientX-rect.left)*1280/rect.width,y=(event.clientY-rect.top)*1280/rect.width,c=Math.floor((x-g.bx)/g.tx),r=Math.floor((y-g.by)/g.ty);return r>=0&&r<g.rows&&c>=0&&c<g.cols?r*g.cols+c:null}
function drawTileOverlay(canvas,obs,selected,legal,mode='add'){let o=normalizeObservation(obs),g=boardGeometry(o),cssW=Math.max(320,canvas.clientWidth||960),dpr=window.devicePixelRatio||1,ctx=canvas.getContext('2d');if(!ctx)return;ctx.setTransform(dpr*cssW/1280,0,0,dpr*cssW/1280,0,0);let legalSet=new Set(list(legal)),selectedSet=new Set(list(selected));for(let r=0;r<g.rows;r++)for(let c=0;c<g.cols;c++){let i=r*g.cols+c,x=g.bx+c*g.tx,y=g.by+r*g.ty;if(legalSet.size&&!legalSet.has(i)){ctx.fillStyle='rgba(20,35,32,.38)';ctx.fillRect(x+2,y+2,g.tx-4,g.ty-4)}if(selectedSet.has(i)){ctx.fillStyle=mode==='erase'?'rgba(232,121,95,.5)':'rgba(75,189,103,.48)';ctx.fillRect(x+5,y+5,g.tx-10,g.ty-10);ctx.strokeStyle=mode==='erase'?'#f3a08a':'#d6f1ab';ctx.lineWidth=4;ctx.strokeRect(x+6,y+6,g.tx-12,g.ty-12)}}}
function cardGeometry(index){return {x:34+index*114,y:84,w:105,h:116}}
function canvasDesignPoint(canvas,event){let rect=canvas.getBoundingClientRect();return {x:(event.clientX-rect.left)*1280/Math.max(1,rect.width),y:(event.clientY-rect.top)*820/Math.max(1,rect.height)}}
function actionCardAt(canvas,obs,event){let point=canvasDesignPoint(canvas,event),cards=list(normalizeObservation(obs).cards);for(let i=0;i<Math.min(8,cards.length);i++){let box=cardGeometry(i);if(point.x>=box.x&&point.x<=box.x+box.w&&point.y>=box.y&&point.y<=box.y+box.h)return String(cards[i].plant_type||'')}return null}
function drawActionCardOverlay(canvas,obs,action){let o=normalizeObservation(obs),cards=list(o.cards),cssW=Math.max(320,canvas.clientWidth||960),dpr=window.devicePixelRatio||1,ctx=canvas.getContext('2d');if(!ctx)return;ctx.setTransform(dpr*cssW/1280,0,0,dpr*cssW/1280,0,0);let feasible=new Set(list(action&&action.feasible)),absolute=new Set(list(action&&action.absolute)),automatic=new Set(list(action&&action.automatic)),availability=action&&action.availability&&typeof action.availability==='object'?action.availability:{};for(let i=0;i<Math.min(8,cards.length);i++){let name=String(cards[i].plant_type||''),box=cardGeometry(i),facts=availability[name]||{};if(facts.available===false||n(cards[i].cooldown_ticks)>0){ctx.fillStyle='rgba(20,35,32,.42)';ctx.fillRect(box.x+2,box.y+2,box.w-4,box.h-4)}if(automatic.has(name)){ctx.fillStyle='rgba(214,184,90,.23)';ctx.fillRect(box.x+3,box.y+3,box.w-6,box.h-6);ctx.strokeStyle='#eadb9f';ctx.setLineDash([8,5]);ctx.lineWidth=3;ctx.strokeRect(box.x+4,box.y+4,box.w-8,box.h-8);ctx.setLineDash([]);ctx.fillStyle='#eadb9f';ctx.font='bold 16px system-ui';ctx.fillText('LOCK',box.x+36,box.y+28)}else if(absolute.has(name)){ctx.fillStyle='rgba(232,121,95,.34)';ctx.fillRect(box.x+3,box.y+3,box.w-6,box.h-6);ctx.strokeStyle='#f3a08a';ctx.lineWidth=4;ctx.strokeRect(box.x+5,box.y+5,box.w-10,box.h-10)}else if(feasible.has(name)){ctx.fillStyle='rgba(75,189,103,.34)';ctx.fillRect(box.x+3,box.y+3,box.w-6,box.h-6);ctx.strokeStyle='#d6f1ab';ctx.lineWidth=4;ctx.strokeRect(box.x+5,box.y+5,box.w-10,box.h-10)}}}
"""
